import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const REQUEST_TYPES = ['휴직', '단축근무'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): ApiError {
  return new ApiError(422, 'LEAVE_REQUEST_INVALID', message);
}

function isBlank(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}

@Controller('api/v1')
export class FnSfr01207Controller {
  @Post('/leave-absence-requests')
  @HttpCode(200)
  async createLeaveAbsenceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const requestType = data['requestType'];
    const startDate = data['startDate'];
    const endDate = data['endDate'];
    const reason = data['reason'];
    if (typeof requestType !== 'string' || !REQUEST_TYPES.includes(requestType)) {
      throw invalid('신청 구분을 확인해 주세요.');
    }
    if (typeof startDate !== 'string' || !DATE_PATTERN.test(startDate)) {
      throw invalid('시작일을 입력해 주세요.');
    }
    if (typeof endDate !== 'string' || !DATE_PATTERN.test(endDate)) {
      throw invalid('종료일을 입력해 주세요.');
    }
    if (typeof reason !== 'string' || reason.trim() === '') {
      throw invalid('신청 사유를 입력해 주세요.');
    }
    let reducedHours: string | null = null;
    if (!isBlank(data['reducedHours'])) {
      const raw = data['reducedHours'];
      const num = Number(raw);
      if (typeof raw === 'boolean' || !Number.isFinite(num) || num <= 0) {
        throw invalid('단축 근무 시간은 0보다 큰 숫자여야 합니다.');
      }
      reducedHours = String(num);
    }
    if (requestType === '단축근무' && reducedHours === null) {
      throw invalid('단축근무는 단축 근무 시간을 입력해야 합니다.');
    }
    let attachmentId: string | null = null;
    if (!isBlank(data['attachmentId'])) {
      const raw = data['attachmentId'];
      const num = Number(raw);
      if (typeof raw === 'boolean' || !Number.isInteger(num) || num <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '증빙 첨부파일 ID 형식이 올바르지 않습니다.');
      }
      attachmentId = String(num);
    }
    return transaction(async (db) => {
      const range = await db.query(
        'SELECT CAST(:startDate AS date) > CAST(:endDate AS date) AS "late"',
        { startDate, endDate },
      );
      if (range[0]['late']) {
        throw invalid('시작일은 종료일보다 늦을 수 없습니다.');
      }
      if (attachmentId !== null) {
        const found = await db.query(
          'SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)',
          { attachmentId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '증빙 첨부파일을 찾을 수 없습니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO leave_absence_request
           (employee_id, attachment_id, request_type, start_date, end_date, reduced_hours, reason, status, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), CAST(:attachmentId AS bigint), :requestType, CAST(:startDate AS date), CAST(:endDate AS date),
            CAST(:reducedHours AS numeric), :reason, '신청', now(), now())
         RETURNING leave_absence_request_id AS "leaveAbsenceRequestId", status AS "status"`,
        { userId: user.id, attachmentId, requestType, startDate, endDate, reducedHours, reason },
      );
      return rows[0];
    });
  }

  @Get('/leave-absence-requests')
  async listLeaveAbsenceRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '인사 담당자');
    const query = checks.queryOf(req.query);
    const pageNum = Number(isBlank(query['page']) ? 0 : query['page']);
    const sizeNum = Number(isBlank(query['size']) ? DEFAULT_SIZE : query['size']);
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(sizeNum) || sizeNum < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeNum, MAX_SIZE);
    const status = isBlank(query['status']) ? null : String(query['status']);
    const requestType = isBlank(query['requestType']) ? null : String(query['requestType']);
    return transaction(async (db) => {
      const params = { status, requestType, limit: size, offset: pageNum * size };
      const where = `(CAST(:status AS text) IS NULL OR status = :status)
         AND (CAST(:requestType AS text) IS NULL OR request_type = :requestType)`;
      const items = await db.query(
        `SELECT leave_absence_request_id AS "leaveAbsenceRequestId",
                employee_id AS "employeeId",
                request_type AS "requestType",
                start_date AS "startDate",
                end_date AS "endDate",
                status AS "status",
                reviewed_at AS "reviewedAt"
           FROM leave_absence_request
          WHERE ${where}
          ORDER BY leave_absence_request_id DESC
          LIMIT :limit OFFSET :offset`,
        params,
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" FROM leave_absence_request WHERE ${where}`,
        { status, requestType },
      );
      return { items, page: pageNum, size, total: Number(counted[0]['total']) };
    });
  }

  @Post('/leave-absence-requests/:leaveAbsenceRequestId/approve')
  @HttpCode(200)
  async approveLeaveAbsenceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = req.params['leaveAbsenceRequestId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM leave_absence_request WHERE leave_absence_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'LEAVE_REQUEST_NOT_FOUND', '신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'LEAVE_REQUEST_ALREADY_PROCESSED', '이미 처리된 신청 건입니다.');
      }
      const rows = await db.query(
        `UPDATE leave_absence_request
            SET status = '승인', reviewer_id = CAST(:userId AS bigint), reviewed_at = now(), updated_at = now()
          WHERE leave_absence_request_id = CAST(:id AS bigint)
          RETURNING status AS "status", reviewed_at AS "reviewedAt"`,
        { id, userId: user.id },
      );
      return rows[0];
    });
  }

  @Post('/leave-absence-requests/:leaveAbsenceRequestId/reject')
  @HttpCode(200)
  async rejectLeaveAbsenceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = req.params['leaveAbsenceRequestId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 ID 형식이 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const rejectReason = data['rejectReason'];
    if (typeof rejectReason !== 'string' || rejectReason.trim() === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM leave_absence_request WHERE leave_absence_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'LEAVE_REQUEST_NOT_FOUND', '신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'LEAVE_REQUEST_ALREADY_PROCESSED', '이미 처리된 신청 건입니다.');
      }
      const rows = await db.query(
        `UPDATE leave_absence_request
            SET status = '반려', reject_reason = :rejectReason, reviewer_id = CAST(:userId AS bigint),
                reviewed_at = now(), updated_at = now()
          WHERE leave_absence_request_id = CAST(:id AS bigint)
          RETURNING status AS "status", reviewed_at AS "reviewedAt"`,
        { id, userId: user.id, rejectReason },
      );
      return rows[0];
    });
  }
}

