import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs,
  Form, Field, TextInput, NumberInput, DateInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 10;
const TYPE_OPTIONS: [string, string][] = [['휴직', '휴직'], ['단축근무', '단축근무']];
const STATUS_OPTIONS: [string, string][] = [['신청', '신청'], ['승인', '승인'], ['반려', '반려']];

export default function FnSfr01207Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [requestType, setRequestType] = useState('');
  const [page, setPage] = useState(0);
  const [applied, setApplied] = useState({ status: '', requestType: '' });
  const [creating, setCreating] = useState(false);
  const [selected, setSelected] = useState<Row | undefined>(undefined);
  const [mode, setMode] = useState<'view' | 'reject'>('view');
  const [rejectReason, setRejectReason] = useState('');
  const [form, setForm] = useState<Row>({ requestType: '', startDate: '', endDate: '', reason: '', reducedHours: '', attachmentId: '' });

  const list = useData<Page>(
    () => call<Page>('GET', '/leave-absence-requests', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/leave-absence-requests', role, undefined, { status: '신청', page: 0, size: 5 }),
    [role],
  );

  const isHr = role === '인사 담당자';

  function refresh() {
    list.reload();
    pending.reload();
  }

  function closeDetail() {
    setSelected(undefined);
    setMode('view');
    setRejectReason('');
  }

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function openDetail(row: Row) {
    setSelected(row);
    setMode('view');
    setRejectReason('');
  }

  async function create() {
    if (!form.requestType || !form.startDate || !form.endDate || !String(form.reason ?? '').trim()) {
      throw new Error('신청 구분, 시작일, 종료일, 신청 사유를 입력해 주세요.');
    }
    if (form.requestType === '단축근무' && (form.reducedHours === '' || form.reducedHours === undefined)) {
      throw new Error('단축근무는 단축 근무 시간을 입력해야 합니다.');
    }
    await call('POST', '/leave-absence-requests', role, {
      requestType: form.requestType,
      startDate: form.startDate,
      endDate: form.endDate,
      reason: form.reason,
      reducedHours: form.reducedHours,
      attachmentId: form.attachmentId,
    });
    notify('신청했습니다.');
    setCreating(false);
    setForm({ requestType: '', startDate: '', endDate: '', reason: '', reducedHours: '', attachmentId: '' });
    refresh();
  }

  async function approve() {
    if (!selected) return;
    await call('POST', `/leave-absence-requests/${selected.leaveAbsenceRequestId}/approve`, role, {});
    notify('승인했습니다.');
    closeDetail();
    refresh();
  }

  async function reject() {
    if (!selected) return;
    if (!rejectReason.trim()) {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    await call('POST', `/leave-absence-requests/${selected.leaveAbsenceRequestId}/reject`, role, { rejectReason });
    notify('반려했습니다.');
    closeDetail();
    refresh();
  }

  function search() {
    setPage(0);
    setApplied({ status, requestType });
  }

  function reset() {
    setStatus('');
    setRequestType('');
    setPage(0);
    setApplied({ status: '', requestType: '' });
  }

  const columns = [
    { key: 'leaveAbsenceRequestId', label: '신청 ID' },
    { key: 'employeeId', label: '신청자', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    { key: 'requestType', label: '신청 구분' },
    { key: 'startDate', label: '시작일', render: (r: Row) => <DateText value={r.startDate} /> },
    { key: 'endDate', label: '종료일', render: (r: Row) => <DateText value={r.endDate} /> },
    { key: 'status', label: '처리 상태', render: (r: Row) => <Badge value={r.status} /> },
    { key: 'reviewedAt', label: '검토 일시', render: (r: Row) => <DateText value={r.reviewedAt} time /> },
  ];

  const pendingColumns = [
    { key: 'employeeId', label: '신청자', render: (r: Row) => <RefName table="employee" role={role} value={r.employeeId} /> },
    { key: 'requestType', label: '신청 구분' },
    { key: 'startDate', label: '시작일', render: (r: Row) => <DateText value={r.startDate} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리 대기</h2>
        <div>{pending.data ? pending.data.total : 0}건</div>
      </section>
      <section className="box span-8">
        <h2>휴직·단축근무 신청</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="처리 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="신청 구분">
            <Select value={requestType} onChange={setRequestType} options={TYPE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={() => setCreating(true)}>신청</button>
        </Band>
        {list.error && <ErrorText text={list.error} />}
        <DataTable columns={columns} rows={list.data?.items ?? []} onRowClick={openDetail} empty="신청 내역이 없습니다." />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      <section className="box span-12">
        <h2>처리 대기 목록</h2>
        {pending.error && <ErrorText text={pending.error} />}
        <DataTable columns={pendingColumns} rows={pending.data?.items ?? []} onRowClick={openDetail} empty="처리 대기 건이 없습니다." />
      </section>

      {creating && (
        <Drawer title="휴직·단축근무 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="신청">
            <Field label="신청 구분" required>
              <Select value={form.requestType} onChange={(v) => setField('requestType', v)} options={TYPE_OPTIONS} />
            </Field>
            <Field label="시작일" required>
              <DateInput value={form.startDate} onChange={(v) => setField('startDate', v)} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={form.endDate} onChange={(v) => setField('endDate', v)} />
            </Field>
            <Field label="단축 근무 시간" hint="단축근무일 때 필수">
              <NumberInput value={form.reducedHours} onChange={(v) => setField('reducedHours', v)} />
            </Field>
            <Field label="신청 사유" required wide>
              <TextInput value={form.reason} onChange={(v) => setField('reason', v)} multiline />
            </Field>
            <Field label="증빙 첨부파일">
              <LookupSelect table="attachment" role={role} value={form.attachmentId} onChange={(v) => setField('attachmentId', v)} />
            </Field>
          </Form>
        </Drawer>
      )}

      {selected && (
        <Drawer title="신청 상세" onClose={closeDetail}>
          <Pairs
            items={[
              ['휴직·단축근무 신청 ID', String(selected.leaveAbsenceRequestId)],
              ['신청자', <RefName table="employee" role={role} value={selected.employeeId} />],
              ['신청 구분', String(selected.requestType)],
              ['시작일', <DateText value={selected.startDate} />],
              ['종료일', <DateText value={selected.endDate} />],
              ['처리 상태', <Badge value={selected.status} />],
              ['검토 일시', <DateText value={selected.reviewedAt} time />],
            ]}
          />
          {isHr && selected.status === '신청' && mode === 'view' && (
            <>
              <Form onSubmit={approve} submit="승인" />
              <button type="button" onClick={() => setMode('reject')}>반려</button>
            </>
          )}
          {isHr && selected.status === '신청' && mode === 'reject' && (
            <Form onSubmit={reject} submit="반려" danger>
              <Field label="반려 사유" required wide>
                <TextInput value={rejectReason} onChange={setRejectReason} multiline />
              </Field>
            </Form>
          )}
        </Drawer>
      )}
    </div>
  );
}
